const code=document.querySelector('#parent-code'),out=document.querySelector('#parent-report'),error=document.querySelector('#report-error');
async function load(){error.textContent='';try{const r=await fetch('/api/parent/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:code.value.trim()})}),data=await r.json();if(!r.ok)throw Error(data.error);out.replaceChildren();const add=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;out.append(e);};add('h2',data.label);add('p','Текущая тема: '+(data.lesson||'ещё не назначена'));const events=data.events,correct=events.filter(e=>e.kind==='answer'&&e.value==='correct').length,retries=events.filter(e=>e.kind==='answer'&&e.value==='retry').length,hints=events.filter(e=>e.kind==='hint').length;add('p','Верных ответов: '+correct+' · Повторных попыток: '+retries+' · Обращений за помощью: '+hints);add('p','Завершено игровых активностей: '+data.games.length);add('h3','Что можно сделать дома');add('p',retries||hints?'Вернитесь к теме вместе: попросите ребёнка показать знакомый пример. Потребность в помощи обсудите с учителем.':'Попросите ребёнка рассказать или показать один шаг занятия. Эти данные описывают действия в приложении, а не общий уровень знаний.');add('h3','История занятия');if(!events.length)add('p','Пока нет действий. Результаты появятся после первого занятия.');for(const e of events.filter(e=>e.kind!=='assistant').slice(0,50)){add('article',new Date(Number(e.created)).toLocaleString('ru-RU')+' · '+e.lesson+' · '+({step:'Открыт шаг '+e.value,hint:'Использована помощь',pause:'Сделан перерыв',answer:e.value==='correct'?'Верный ответ':'Повторная попытка'}[e.kind]||e.kind));}document.querySelector('#parent-form').hidden=true;}catch(e){error.textContent=e.message;}}
document.querySelector('#parent-form').onsubmit=e=>{e.preventDefault();load();};if(location.hash){code.value=location.hash.slice(1);history.replaceState(null,'',location.pathname);load();}
